import React, { useState } from "react";
import { FiEdit } from "react-icons/fi";
import { FaTrash } from "react-icons/fa";
import AdminEditProduct from "./AdminEditProduct";

export default function AdminProductList() {
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const products = [
    { id: 1, name: "Product Name", price: "100", stocks: 100 },
    { id: 2, name: "Product Name", price: "100", stocks: 100 },
    { id: 3, name: "Product Name", price: "100", stocks: 100 },
    { id: 4, name: "Product Name", price: "100", stocks: 100 },
    { id: 5, name: "Product Name", price: "100", stocks: 100 },
  ];

  const openEdit = (product) => {
    setSelectedProduct(product);
    setEditModalOpen(true);
  };

  return (
    <div className="admin-main">
    <div className="table-container">
        <table className="admin-table">
        <thead>
            <tr>
            <th>ID</th>
            <th>PRODUCT NAME</th>
            <th>PRICE</th>
            <th>STOCKS</th>
            <th className="text-right">ACTIONS</th>
            </tr>
        </thead>
        <tbody>
  {products.map((p) => (
    <tr key={p.id}>
      <td><div className="td-card">{p.id}</div></td>
      <td><div className="td-card">{p.name}</div></td>
      <td><div className="td-card">{p.price}</div></td>
      <td><div className="td-card">{p.stocks}</div></td>
      <td>
        <div className="td-card actions">
          <FiEdit size={20} className="cursor-pointer" onClick={() => openEdit(p)} />
          <FaTrash size={20} color="#FF0000" className="cursor-pointer ml-4" />
        </div>
      </td>
    </tr>
  ))}
</tbody>


        </table>
    </div>

    {editModalOpen && selectedProduct && (
        <AdminEditProduct
        isOpen={editModalOpen}
        onClose={() => setEditModalOpen(false)}
        product={selectedProduct}
        />
    )}
    </div>

  );
}
